// Delete photos older than 12 months, then null the paths.
// This is what keeps the Supabase free tier — and the $0/month promise — intact.

const SUPABASE_URL = $env.SUPABASE_URL;
const KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const hdr = { apikey: KEY, Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' };

const expired = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/expired_photos?select=*`,
  headers: hdr, json: true,
});

if (!expired.length) return [{ json: { deleted: 0, message: 'Nothing to prune' } }];

const paths = [];
for (const row of expired) {
  if (row.clockin_photo_path) paths.push(row.clockin_photo_path);
  if (row.clockout_photo_path) paths.push(row.clockout_photo_path);
}

// Storage delete accepts up to 1000 paths per call.
for (let i = 0; i < paths.length; i += 500) {
  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `${SUPABASE_URL}/storage/v1/object/site-photos`,
    headers: hdr,
    body: { prefixes: paths.slice(i, i + 500) },
    json: true,
  });
}

for (const row of expired) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/site_visits?id=eq.${row.visit_id}`,
    headers: { ...hdr, Prefer: 'return=minimal' },
    body: { clockin_photo_path: null, clockout_photo_path: null },
    json: true,
  });
}

return [{ json: { deleted: paths.length, visits: expired.length } }];
